"""Build the browser preview without exposing unrelated workspace files."""

from pathlib import Path
import shutil

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "prototype"
DESTINATION = ROOT / "dist"


def main():
    # Only the directory generated by this script is replaced.
    if DESTINATION.is_symlink():
        raise RuntimeError("Refusing to replace a symlink at dist")
    if DESTINATION.exists():
        shutil.rmtree(DESTINATION)
    DESTINATION.mkdir()
    shutil.copy2(SOURCE / "weekly.html", DESTINATION / "index.html")
    shutil.copytree(SOURCE / "assets", DESTINATION / "assets")
    (DESTINATION / ".nojekyll").touch()
    print(f"Built preview: {DESTINATION / 'index.html'}")


if __name__ == "__main__":
    main()
